function multiplyStrings(a: string, b: string): string {
  if (a === "0" || b === "0") return "0";
  const add = (x: string, y: string): string => {
    let i = x.length - 1, j = y.length - 1, carry = 0, out = "";
    while (i >= 0 || j >= 0 || carry) {
      const s = (i >= 0 ? +x[i--] : 0) + (j >= 0 ? +y[j--] : 0) + carry;
      out = (s % 10) + out;
      carry = Math.floor(s / 10);
    }
    return out;
  };
  let total = "0";
  for (let j = b.length - 1; j >= 0; j--) {
    const d = +b[j];
    let carry = 0, part = "";
    for (let i = a.length - 1; i >= 0; i--) {
      const p = +a[i] * d + carry;
      part = (p % 10) + part;
      carry = Math.floor(p / 10);
    }
    if (carry) part = carry + part;
    total = add(total, part + "0".repeat(b.length - 1 - j));
  }
  return total.replace(/^0+(?=\d)/, "");
}

