class Solution:
    def multiplyStrings(self, a: str, b: str) -> str:
        if a == "0" or b == "0":
            return "0"
        def add(x: str, y: str) -> str:
            i, j, carry, out = len(x) - 1, len(y) - 1, 0, []
            while i >= 0 or j >= 0 or carry:
                s = carry
                if i >= 0:
                    s += ord(x[i]) - 48
                    i -= 1
                if j >= 0:
                    s += ord(y[j]) - 48
                    j -= 1
                carry, d = divmod(s, 10)
                out.append(str(d))
            return "".join(reversed(out))
        total = "0"
        for j in range(len(b) - 1, -1, -1):
            d, carry, part = ord(b[j]) - 48, 0, []
            for i in range(len(a) - 1, -1, -1):
                carry, v = divmod((ord(a[i]) - 48) * d + carry, 10)
                part.append(str(v))
            if carry:
                part.append(str(carry))
            total = add(total, "".join(reversed(part)) + "0" * (len(b) - 1 - j))
        return total.lstrip("0") or "0"

