function multiplyStrings(a: string, b: string): string {
  const m = a.length, n = b.length;
  const slots = new Array(m + n).fill(0);
  for (let i = 0; i < m; i++) {
    const da = a.charCodeAt(i) - 48;
    for (let j = 0; j < n; j++) slots[i + j + 1] += da * (b.charCodeAt(j) - 48);
  }
  for (let k = m + n - 1; k > 0; k--) {
    slots[k - 1] += Math.floor(slots[k] / 10);
    slots[k] %= 10;
  }
  let start = 0;
  while (start < slots.length - 1 && slots[start] === 0) start++;
  return slots.slice(start).join("");
}

